// One acceptance criterion's verdict. `criterion_id` refers to the run's frozen test case snapshot, so
// editing the draft afterwards cannot rewrite what was judged (iron rule 4).
// Ref: #/components/schemas/CriterionResult
type CriterionResult struct {
	CriterionID string `json:"criterion_id"`
	// The wording as it stood in the snapshot, carried here so an evaluation report stays readable without
	// resolving the snapshot — and so it keeps showing the words that were actually judged.
	Text string `json:"text"`
	// `undetermined` whenever the evidence does not settle it: input was truncated, an evidence reference
	// did not resolve, or the trace was incomplete. It is one of EVAL-001's required states, not a missing
	// answer, and it is what the pipeline falls back to on any doubt.
	Result CriterionResultResult `json:"result"`
	// Who decided, and required rather than optional: EVAL-001 第 5 條 requires a model's judgement to
	// be labelled as a model's, and an omitted field would read as a platform fact.
	//
	// The control plane sets this from where the verdict actually came, never from what the model reports
	// about itself — the judge service's response has no such field to fill in. `rule` is a
	// deterministic check over the platform's own records, `user` is a person's verdict recorded over the
	// automated one.
	Source CriterionResultSource `json:"source"`
	// What the verdict rests on. Every reference a model returns is re-checked server-side before it is
	// stored; one that does not resolve drops the verdict to `undetermined` instead of being passed
	// through as given.
	Evidence []EvidenceRef `json:"evidence"`
	// Why, in the user's language. Untrusted text when `source` is `model`: render it as inert text like
	// any other model output.
	Reason string `json:"reason"`
}

