// One built package (PACK-001). Immutable: re-packaging produces another row, never an edit of this
// one (iron rule 4).
//
// Two hashes, answering two different questions. `content_hash` is over the zip bytes and answers "is
// this the file I had". `manifest_hash` is canonical over `{path: sha256}` with no zip metadata and
// not covering the manifest itself, and answers "is the content the same as last time" — which is
// what deduplication and "did the skill change or only the profile" need, and what a byte hash cannot
// answer across packager versions (packaging-design §2.4).
// Ref: #/components/schemas/DownloadArtifact
type DownloadArtifact struct {
	ArtifactID     uuid.UUID `json:"artifact_id"`
	SkillID        uuid.UUID `json:"skill_id"`
	SkillVersionID uuid.UUID `json:"skill_version_id"`
	// Which version these bytes are, in the monotonic per-skill numbering the immutability trigger
	// protects. The uuid beside it identifies the row; this is the only field on this schema a person can
	// read as an answer to "which one is this" (04 丙-42, `02:WS-002` 1「版本」).
	VersionNumber int `json:"version_number"`
	// The highest version number this skill currently has. Present so the client never has to fetch a
	// second resource to find out whether it is showing a stale package, and equal to `version_number`
	// when this is the newest.
	LatestVersionNumber int `json:"latest_version_number"`
	// `current` or `superseded`, with the wording — including the numbers — from the server
	// (設計系統 §4.4).
	//
	// Deliberately not a fifth `serve_state`. Being superseded says nothing about whether the bytes are
	// available: a superseded package is downloadable, and downloading exactly the version you packaged is
	// a legitimate thing to want. `serve_state` answers "can I have the bytes"; this answers "is this the
	// newest content". Folding them would make one field mean two things and force a
	// superseded-and-expired row to pick which truth to tell (設計系統 §2.12 的第三軸).
	//
	// It is not upstream freshness. Whether the source the skill was imported from has moved is
	// `CONTENT-009`/`INGEST-010`, neither of which is built, and whose re-fetch cadence is still
	// 待決策.
	VersionState Labelled          `json:"version_state"`
	Target       PackagingTargetId `json:"target"`
	// Display and attachment name only. Like a dataset's, it is never used as a storage path.
	FileName     string `json:"file_name"`
	SizeBytes    int64  `json:"size_bytes"`
	ContentHash  string `json:"content_hash"`
	ManifestHash string `json:"manifest_hash"`
	// The artifact's own scan state (ADR-003: an upload is quarantined until it passes its checks), not a
	// `ready` boolean. `rejected` and `quarantined` are two different things to the person waiting for a
	// download — one is over and one is not — and one flag would say neither.
	//
	// Only `available` is served by GET /downloads/{artifactId}/content. That is the point of keeping the
	// state: the rule is a condition on one handler that a test can hold to, rather than a habit of not
	// handing bytes over too early.
	Status DownloadArtifactStatus `json:"status"`
	// Whether GET /downloads/{artifactId}/content would hand the bytes over right now:
	// `status == available` AND the stored object has not been purged AND `expires_at` is still in the
	// future (skill/delivery/download.go). Served rather than derived (04 丙-29 ⑤) because one of its
	// three inputs — the purge — is not on this schema at all, so no client can compute it and every
	// client that tried was computing something else.
	//
	// The three parts stay visible beside it: `status` says which check, `expires_at` says when, and this
	// says the answer. Folding them into one flag would lose why (`quarantined` is not over, `rejected`
	// is).
	Servable bool `json:"servable"`
	// The one sentence for the composite above — 「可下載」, 「檢查中」, 「已拒絕」,
	// 「已過期，不再提供下載」, 「檔案遺失，不再提供下載」. `value` is the state
	// that decided it, which is `status` except when an `available` artifact has expired, been purged, or
	// been found missing, where it is `expired`, `purged` or `lost` — values that do not appear in
	// `status` at all, which is why a label on `status` alone would have fought the word on the screen
	// instead of settling it (設計系統 §2.2 顯示但不強制).
	//
	// `lost` is separated from `expired` on purpose (04 丙-91). Both mean the bytes are gone and both are
	// answered by packaging the same version again, but expiry is the retention promise being kept while
	// loss is the platform dropping something inside that promise. Telling an owner their file expired
	// when it was lost is a true sentence about the wrong cause, and it removes the one reason they had to
	// report it. The server decides which; a client must not re-derive it, and must not print retention
	// copy beside `lost`.
	ServeState Labelled `json:"serve_state"`
	// When the object is deleted. The retention period is deployment configuration; PDM-006 proposes 90
	// days for download packages and that proposal is not ratified yet, so no number is fixed here.
	//
	// Show it as an absolute date, never as "in N days" (PDM-006 risk table), and alongside the fact that
	// the same version can be packaged again at any time — which is true because packaging is
	// idempotent. Expiry deletes the object and this row; the download records it produced are kept,
	// because "you downloaded this" stays true.
	ExpiresAt time.Time `json:"expires_at"`
	CreatedAt time.Time `json:"created_at"`
	// How many times the bytes were actually served.
	DownloadCount int `json:"download_count"`
	// Whether the PACK-005 test cases travelled. Part of the idempotency key, so the same version packaged
	// with and without them is two artifacts rather than one that quietly changed.
	IncludesTestCases bool `json:"includes_test_cases"`
	// The builder that produced these bytes. `content_hash` is reproducible within one packager version
	// and not guaranteed across them, which is exactly why the version is recorded rather than assumed.
	PackagerVersion OptString `json:"packager_version"`
	// The target profile's version. Absent for `standard`, which has no profile.
	ProfileVersion OptString `json:"profile_version"`
}

