// The artifact's own scan state (ADR-003: an upload is quarantined until it passes its checks), not a
// `ready` boolean. `rejected` and `quarantined` are two different things to the person waiting for a
// download — one is over and one is not — and one flag would say neither.
//
// Only `available` is served by GET /downloads/{artifactId}/content. That is the point of keeping the
// state: the rule is a condition on one handler that a test can hold to, rather than a habit of not
// handing bytes over too early.
type DownloadArtifactStatus string

const (
	DownloadArtifactStatusQuarantined DownloadArtifactStatus = "quarantined"
	DownloadArtifactStatusAvailable   DownloadArtifactStatus = "available"
	DownloadArtifactStatusRejected    DownloadArtifactStatus = "rejected"
)

// AllValues returns all DownloadArtifactStatus values.
func (DownloadArtifactStatus) AllValues() []DownloadArtifactStatus {
	return []DownloadArtifactStatus{
		DownloadArtifactStatusQuarantined,
		DownloadArtifactStatusAvailable,
		DownloadArtifactStatusRejected,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s DownloadArtifactStatus) MarshalText() ([]byte, error) {
	switch s {
	case DownloadArtifactStatusQuarantined:
		return []byte(s), nil
	case DownloadArtifactStatusAvailable:
		return []byte(s), nil
	case DownloadArtifactStatusRejected:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *DownloadArtifactStatus) UnmarshalText(data []byte) error {
	switch DownloadArtifactStatus(data) {
	case DownloadArtifactStatusQuarantined:
		*s = DownloadArtifactStatusQuarantined
		return nil
	case DownloadArtifactStatusAvailable:
		*s = DownloadArtifactStatusAvailable
		return nil
	case DownloadArtifactStatusRejected:
		*s = DownloadArtifactStatusRejected
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

