// One judgement of one run (EVAL-001), and a resource of its own because it answers a question `Run`
// does not. `Run.status` records what happened during execution; `Evaluation.overall` records whether
// the task was achieved. `succeeded` is an execution outcome and never a task verdict, an evaluation
// never writes back to the run, and the two are not to be merged into a single pass/fail on any screen
// (ADR-025, NFR-001).
//
// `status` and `overall` are likewise two fields on purpose. `status` is about the judgement (did it
// run at all), `overall` is about the task (what did it conclude). With only one of them, "the
// evaluator broke" and "the evidence does not settle it" would be indistinguishable.
// Ref: #/components/schemas/Evaluation
type Evaluation struct {
	EvaluationID uuid.UUID `json:"evaluation_id"`
	RunID        uuid.UUID `json:"run_id"`
	// Whether the judgement itself ran. `failed` means it could not be produced — the model gateway was
	// unavailable, the evidence could not be read — and is shown as 評估未完成, never quietly
	// turned into a lenient verdict. It is a different thing from having no evaluation at all, which is a
	// 404 rather than a row.
	Status EvaluationStatus `json:"status"`
	// Whether the task was achieved. Never derived from the run's terminal state. `undetermined` is the
	// safe default: it is the answer whenever the evidence does not settle the question, and it is what a
	// `pending` or `failed` evaluation reports.
	Overall EvaluationOverall `json:"overall"`
	// Human-readable verdict, for display above the per-criterion detail. On `status: failed` it states
	// what stopped the judgement instead.
	Summary OptString `json:"summary"`
	// One entry per acceptance criterion in the run's snapshot, not the editable test case (iron rule 4).
	CriterionResults []CriterionResult `json:"criterion_results"`
	// Kept apart from `criterion_results` because the two answer different questions: "what is wrong with
	// this run" versus "did this criterion pass". An empty list is not a clean bill of health.
	DeterministicFindings []DeterministicFinding `json:"deterministic_findings"`
	// The model that produced the `model`-sourced verdicts (EVAL-001 第 5 條). Empty when no judge ran
	// at all - a run with no acceptance criteria is settled without one - because naming a model here
	// would describe a call that was never made.
	JudgeModel string `json:"judge_model"`
	// The judge prompt this verdict was reached under (ADR-017). Together with `rubric_version` it is what
	// makes two revisions comparable.
	JudgePromptVersion string `json:"judge_prompt_version"`
	// The CONTENT-007 rubric in force. Absent when the skill's category has none — absent means "no
	// rubric", not "the default rubric".
	RubricVersion OptString `json:"rubric_version"`
	// False when the material judged was incomplete: the run trace has a hole (`complete: false` on GET
	// /runs/{id}/trace), an artifact could not be read, or an input had to be truncated. A criterion
	// judged on incomplete evidence must not come back `passed`; `undetermined` is the honest outcome and
	// the UI has to keep saying so (ADR-009).
	EvidenceComplete bool           `json:"evidence_complete"`
	Cost             EvaluationCost `json:"cost"`
	// The user's own answer about this judgement (EVAL-001 第 4 條). Absent means nobody answered, which
	// is not the same as "not helpful".
	Feedback    OptEvaluationFeedback `json:"feedback"`
	EvaluatedAt time.Time             `json:"evaluated_at"`
	// Set when a later re-evaluation replaced this one; null on the current revision. Returned so that
	// reading an old revision through `?revision=` cannot be mistaken for reading the standing verdict.
	SupersededAt OptNilDateTime `json:"superseded_at"`
}

