// One proposed improvement (EVAL-002). It belongs to the evaluation that produced it rather than to
// the run: re-evaluating under another rubric produces its own set, and merging them would present
// suggestions about different verdicts as one list.
//
// The descriptive fields are frozen once written — what a model proposed is a fact about what was
// proposed. Only the decision fields move.
// Ref: #/components/schemas/ImprovementSuggestion
type ImprovementSuggestion struct {
	SuggestionID uuid.UUID `json:"suggestion_id"`
	// Which layer the problem is in (EVAL-002 第 2 條). `mcp` is never produced in the MVP — remote
	// MCP is out of first release — and exists so the value does not have to be added to a live enum
	// later, the same placement TRACE-003 already uses.
	Category ImprovementSuggestionCategory `json:"category"`
	// What went wrong. Model-written; render as inert text.
	Problem string `json:"problem"`
	// Why the model believes it, in verifiable form. Same server-side re-check as on a criterion verdict.
	Evidence []EvidenceRef `json:"evidence"`
	// Package-relative path the change applies to. Normalised and checked again when it is applied;
	// anything resolving outside the package is refused there as `path_out_of_bounds`.
	TargetPath string `json:"target_path"`
	// What the model expects to improve. A prediction, not a measurement.
	ExpectedImpact string `json:"expected_impact"`
	// The user's per-suggestion decision (EVAL-002 第 3 條). `pending` is the starting state. Accepting
	// records agreement only — nothing is written to any package until POST
	// /skills/{id}/versions/from-suggestions is called.
	Decision  ImprovementSuggestionDecision `json:"decision"`
	DecidedAt OptDateTime                   `json:"decided_at"`
	// The new version this suggestion went into, once one was built. Absent means it has not been applied.
	// The version it was written against is untouched either way (iron rule 4).
	AppliedSkillVersionID OptUUID `json:"applied_skill_version_id"`
}

