// One packaging target and what installing it involves (PACK-002, PACK-006/007/008).
// Ref: #/components/schemas/PackagingTarget
type PackagingTarget struct {
	ID PackagingTargetId `json:"id"`
	// `standard_package` — the Agent Skills spec package itself, with no agent-specific adaptation.
	// `profile` — a versioned set of install settings for one agent.
	//
	// Two values rather than one flat list of profiles, because the standard package is what makes "Skill
	// Hub is not tied to one agent" checkable (PDM-008): its SKILL.md is unchanged from the source
	// version, byte for byte, and a profile's is not.
	Kind PackagingTargetKind `json:"kind"`
	// The profile's own version, recorded in the package manifest so a downloaded package says which
	// settings produced it. The standard package reports the packager's version instead — there is no
	// profile to version.
	Version     string `json:"version"`
	DisplayName string `json:"display_name"`
	// Where the package goes, in the words the install instructions use. Absent for `standard_package`,
	// which makes no claim about any agent's layout.
	//
	// The two profiles resolve to the same path today and differ in which layer it is — a user-level or
	// project-level skills directory versus an agent's working directory — so the copy has to state the
	// difference or the two read as one option listed twice (PDM-008 v4).
	InstallLocation OptString `json:"install_location"`
	// `verified` — Skill Hub has actually installed and run a package through this target. `unverified`
	// — it has not, and nothing here promises the package will work (02:PACK-002 第 2 條). The
	// standard package is `unverified` by construction: any spec-compliant agent may try it, and Skill Hub
	// has not tried it on yours.
	//
	// It is a property of the target, not of a skill. Whether a particular version was ever measured is
	// the `compatibility` axes on the skill, and passing format validation is never permission to say it
	// installs (ADR-012).
	SupportStatus PackagingTargetSupportStatus `json:"support_status"`
	// A prompt to run against the target agent once the package is installed, to see whether the Skill was
	// actually picked up (02:PACK-002 第 3 條). Absent for `standard_package`, which names no agent to
	// run a prompt against — its check is `verification_steps`.
	VerificationPrompt OptString `json:"verification_prompt"`
	// Post-install checks, in order. Every target has at least one of these two fields; both are optional
	// here because which one a target carries depends on whether it names an agent.
	//
	// Served rather than left to the INSTALL.md inside the package: a check that only exists inside a
	// package the user has not built yet is not available on the page where they are choosing a target,
	// and 02:PACK-002 第 3 條 asks for the check itself, not for a promise that one ships.
	VerificationSteps []string `json:"verification_steps"`
	// The environment variables this target needs, and the other half of 02:PACK-002 第 1 條's
	// "依賴與環境變數需求". A property of the target rather than of the skill: the SDK target
	// needs its API key whichever Skill is inside, and the skill's own dependencies are on the packaging
	// preview, which is where the package's bytes are known.
	//
	// Served rather than left to the INSTALL.md inside the package, for the same reason as
	// `verification_steps`: a requirement the user only discovers after building the package is not on the
	// page where they choose a target. Empty array for a target that needs none — the standard package
	// names no agent and therefore no variable.
	EnvVars []PackagingTargetEnvVarsItem `json:"env_vars"`
	// Known limitations and the steps a path alone does not cover — for the SDK target, that `cwd` and
	// `setting_sources` are part of installing and a skill silently never loads without them (ADR-023).
	// Server-side so every surface states them identically (NFR-001).
	Notes []string `json:"notes"`
}

