// Ref: #/components/schemas/PublicSearchResult
type PublicSearchResult struct {
	SkillID uuid.UUID `json:"skill_id"`
	Name    string    `json:"name"`
	// Plain summary (DISC-002). The index-time LLM summary when the skill has been enriched (ADR-013 §1,
	// model-generated), otherwise the package's own frontmatter description. `summary_source` says which,
	// because until it existed this sentence was documented as sometimes model-written and had no field a
	// client could act on.
	Summary string `json:"summary"`
	// Who wrote `summary`. ADR-013 requires model-generated content to be labelled, and this row was
	// already labelling `match_reason` while printing the model's rewrite of the summary unmarked — the
	// footnote carried the badge and the sentence a reader decides on did not.
	//
	// `package` also carries a second fact worth knowing: it is the `description` an agent actually reads
	// when it decides whether to load this Skill. A `model` summary is not that text, so a Skill can read
	// well here and be passed over by the agent, and nothing about the enriched summary changes what the
	// downloaded package says.
	SummarySource PublicSearchResultSummarySource `json:"summary_source"`
	// Cosine similarity to the query, 0..1, higher is better (DISC-002 — never star count). Search
	// results with a non-null rank are ordered by it.
	//
	// Null when this page was not ranked by similarity, and the ordering is then something else entirely
	// — see `rank_note`. Three cases reach it: the whole answer came from the lexical leg (`degraded`),
	// this one row has no embedding yet (`partial_index`), or the row belongs to the browse catalog, which
	// uses its documented catalog ordering. The lexical score is not returned in its place: `ts_rank_cd`
	// is unbounded (a local answer measured 1.4) and is not the same quantity as a cosine similarity, so
	// squeezing it into 0..1 would be false precision.
	Rank NilFloat64 `json:"rank"`
	// Why `rank` is null and what ordered the page instead. Present only when `rank` is null.
	RankNote OptString `json:"rank_note"`
	// PDM-001 category (DISC-002 類別): `documents` | `writing` | `data`, or `unassigned` when the
	// platform has not given this skill one. `unassigned` is a typed absence, worded 尚未定值: every
	// user-imported skill carries it until 05 R-19 decides how such a skill gets a category, and a fork
	// inherits its source's value (migration 0053). The label is the shelf name a reader sees; the note
	// says where the value came from — a curation judgement, never a guess.
	Category Labelled `json:"category"`
	// Collection tier (DISC-002 來源層級): `curated` | `indexed`, resolved per row against the skill's
	// newest version — see the `tier` query parameter for what `indexed` does and does not mean.
	// `external` never appears here: a result in this list was imported by definition.
	Tier Labelled         `json:"tier"`
	Risk SearchResultRisk `json:"risk"`
	// Dependency tags from the index-time enrichment (DISC-002 依賴). Model-extracted from what the
	// package's own documentation states — not a resolved dependency graph, and empty while enrichment
	// is pending.
	Dependencies []string `json:"dependencies"`
	// Same three axes as the detail view (DISC-002 Agent 相容狀態). `spec_validation` is `passed` for
	// any row with a saved version: static validation is what admits a package to the index, so being
	// listed here is the evidence. It is `unverified` only for a skill with no version yet. `capability`
	// and `runtime` carry the measured verdict when the projection holds one, and stay `unverified` when
	// it does not — that is the 「尚未試跑」 state DISC-002 requires to be explicit, and it is
	// what `runtime_image` being absent means.
	Compatibility SkillCompatibility `json:"compatibility"`
	// When the listed content was last validated (DISC-002 最近驗證時間): the creation time of the
	// latest saved version, which is the import that scanned it. Versions are immutable, so this cannot
	// drift from the content it describes. Absent for a skill with no saved version.
	VerifiedAt OptDateTime `json:"verified_at"`
	// Human-readable explanation of why this skill matches the query (DISC-002). Template-based fallback
	// when LLM polish times out.
	MatchReason OptString `json:"match_reason"`
	// Provenance of match_reason. ADR-013 requires model-generated content to be labelled, so the UI can
	// mark it as such. `template` reasons are assembled from the query/document lexical overlap, or state
	// plainly that the hit came from semantic similarity with no shared keywords.
	MatchReasonSource OptPublicSearchResultMatchReasonSource `json:"match_reason_source"`
}

