// llm-internal.yaml's RubricItem, because it is the same object: what is stored here is what
// /judge-run is sent.
// Ref: #/components/schemas/RubricItem
type RubricItem struct {
	// The id of the acceptance criterion this item strengthens, not an id of its own. /judge-run answers
	// one verdict per criterion id and the platform drops any id it did not send, so an item naming
	// something else could never produce a stored verdict. An item whose criterion is deleted is removed
	// with it.
	ID   string `json:"id"`
	Text string `json:"text"`
	// The author's relative-importance signal, passed to the model as written. Nothing in the platform
	// does arithmetic on it: the overall verdict is recomputed from the per-criterion results, so this is
	// not a score. Absent means the author gave none.
	Weight OptFloat64 `json:"weight"`
	// Whether this item's verdict must come back with a quotation. Per item rather than a global switch,
	// because a quote can show that something is present and cannot show that something is absent.
	EvidenceRequired bool `json:"evidence_required"`
}

