// One run as the Web surface sees it. The provider-facing shapes are a separate contract
// (contracts/openapi/sandbox-provider.yaml) and nothing provider-specific leaks into this one
// (RUN-001).
// Ref: #/components/schemas/Run
type Run struct {
	// The permanent platform identifier (iron rule 10).
	RunID uuid.UUID `json:"run_id"`
	// The standard lifecycle of ADR-004 / RUN-002. `cleaning_up` is not in here: cleanup happens after a
	// terminal state and is reported separately in `cleanup_status`, so "the run failed" and "its sandbox
	// was torn down" stay two distinct facts.
	//
	// `succeeded` says the workload finished, not that the task was done. Whether it was is
	// `Evaluation.overall` from GET /runs/{id}/evaluation, which is a separate resource an evaluation
	// never writes back into (ADR-025). A surface showing this value alone must word it as execution
	// (執行完成 / 執行失敗) and must not present it as a pass.
	Status RunStatus `json:"status"`
	// Why the run entered this status. Masked and safe to display.
	//
	// Two kinds of sentence arrive here and the difference matters. Most are the platform's own, and those
	// are served in the interface language. Some are relayed verbatim from the provider that ran the
	// workload (`state_reason` on the provider contract), and the platform does not rewrite another
	// system's words — so a reader can meet an English sentence here, and that is the mark of a relayed
	// one (04 丙-115 ①).
	StatusReason OptString `json:"status_reason"`
	// The skill the version belongs to. Served rather than left to the client to work out: applying
	// improvement suggestions posts to POST /skills/{id}/versions/from-suggestions, and a run page that
	// had to be reached with the id already in its URL could only offer that action to callers who arrived
	// the one right way.
	//
	// It is a fact about the version, not about the run: a run never moves between skills, and this
	// changes for no reason at all.
	SkillID        uuid.UUID `json:"skill_id"`
	SkillVersionID uuid.UUID `json:"skill_version_id"`
	// The frozen copy taken when the run was created, not the editable test case (iron rule 4).
	TestCaseSnapshotID uuid.UUID `json:"test_case_snapshot_id"`
	// The editable test case the snapshot was frozen from, which is what a re-run needs: POST
	// /skills/{id}/runs takes a test case and snapshots it again, and the snapshot id cannot be handed
	// back to it.
	//
	// Optional, so that a reader which no longer resolves is an absent field rather than an id pointing at
	// nothing. Absent rather than null, like every other optional id in this contract.
	//
	// Present is not permission to re-run. The draft may have been deleted or its datasets may be gone —
	// `inputs_available` on GET /runs/{id}/comparison is what answers that — and a re-run goes through
	// preflight and `confirmed_summary_hash` either way (TEST-009).
	TestCaseID OptUUID `json:"test_case_id"`
	// `unassigned` until provider selection lands (RUN-005).
	Provider string `json:"provider"`
	// The same field, the same values and the same words as `RunListItem.failure_class` — see there.
	//
	// Declared here on 2026-09-01, having been served long before. `GET /runs/{id}` returned it while this
	// schema did not mention it, so every generated client was missing the one field that says why a run
	// failed — and nothing could notice: the Go side is models-only with hand-written handlers
	// (ADR-030's 2026-08-29 note), so a handler can serve what the contract never declared.
	FailureClass OptLabelled `json:"failure_class"`
	// Tracked apart from the run outcome, and still writable after a terminal state. Idempotent cleanup is
	// RUN-007. `value` is the database enum; see RunListItem.cleanup_status for why it is served with its
	// words.
	CleanupStatus Labelled `json:"cleanup_status"`
	// Set by POST /runs/{id}/cancel. Intent, not the outcome.
	CancelRequestedAt OptDateTime `json:"cancel_requested_at"`
	CreatedAt         time.Time   `json:"created_at"`
	StartedAt         OptDateTime `json:"started_at"`
	FinishedAt        OptDateTime `json:"finished_at"`
	// Every state change with its time and reason (RUN-002). Append-only and oldest first; the first entry
	// has no `from_status` because it is the run's creation.
	Transitions []RunTransitionsItem `json:"transitions"`
	// One entry per execution attempt (RUN-003). The provider's ephemeral id hangs off the attempt that
	// owns it, so a retry adds a mapping instead of overwriting the previous one.
	Attempts []RunAttemptsItem `json:"attempts"`
}

