// Each side reports execution and task judgement in separate fields, and an unevaluated side says so
// rather than leaving the reader to infer a pass from `succeeded` (ADR-025).
// Ref: #/components/schemas/RunComparison
type RunComparison struct {
	// The run named in the path first, the `against` run second.
	Runs []RunComparisonRunsItem `json:"runs"`
	// One row per acceptance criterion with both runs' verdicts, so a regression shows up per criterion
	// instead of only in the overall. Criteria are matched by `criterion_id`, which the two snapshots
	// share when the same test case was re-run (equal `content_hash`); one present on only a single side
	// carries a null verdict for the other rather than being dropped.
	CriterionMatrix []RunComparisonCriterionMatrixItem `json:"criterion_matrix"`
	// Where to see what changed between the two skill versions: the existing GET /skills/{id}/diff with
	// `from` and `to` filled in (WS-003), not a second diff implementation. Absent when both runs used the
	// same version, and absent when they used versions of different skills — that diff does not exist,
	// and inventing a cross-skill one would be a second diff implementation for a comparison nobody asked
	// for.
	VersionDiffURL OptString `json:"version_diff_url"`
}

