// Everything a run will be able to touch, shown before it starts (TEST-005/008). Built for a (skill
// version, test case draft) pair and never stored: it is recomputed on every read, so it always
// describes the run as it would start right now.
// Ref: #/components/schemas/RunPermissionSummary
type RunPermissionSummary struct {
	Summary RunPermissionSummaryContent `json:"summary"`
	// SHA-256 over a canonical encoding of `summary` and nothing else. Both the confirmation and the run
	// request quote it back, and the server recomputes it rather than trusting either, so it is an
	// integrity check on what the user saw and not a token.
	SummaryHash string `json:"summary_hash"`
	// What the run is predicted to cost. Outside the hash, like `notes` and for the same reason: the hash
	// covers what the run is allowed to touch, and a prediction is not a permission. Recalibrating the
	// numbers against a larger sample must not silently revoke every confirmation a user has outstanding.
	EstimatedCost RunCostEstimate `json:"estimated_cost"`
	// What the account has left (PDM-010), shown here because it answers the same kind of question
	// `estimated_cost` does — what this run will use up — and the screen where a user decides to start
	// one is where that belongs.
	//
	// Outside the hash, for the same reason and by the same rule TEST-011 set for `estimated_cost`: the
	// hash covers what the run is allowed to touch, and an allowance is a state, not a permission. A run
	// finishing elsewhere in the workspace must not invalidate a confirmation the user is holding.
	//
	// Absent when the deployment enforces no allowance. Absent rather than zeroed or filled with nulls: a
	// number on this screen is a claim that it is applied (04 乙-2), so a build with no enforcement shows
	// nothing at all.
	Quota OptRunQuota `json:"quota"`
	// Plain-language explanation of the summary, deliberately outside the hash. Rewording a sentence must
	// not invalidate every outstanding confirmation, and the facts are in `summary` where the hash covers
	// them.
	Notes []string `json:"notes"`
}

