// The hashed body: the eight TEST-008 disclosures plus what they belong to. Field order is fixed by
// the server's type rather than by an encoder, because the hash depends on it.
//
// Deliberately absent: the user prompt and the acceptance criteria. Editing either changes what the
// run is asked to do, not what it is allowed to touch, and invalidating a permission agreement over a
// typo fix would train users to click through the one screen that must not be reflexive.
// Ref: #/components/schemas/RunPermissionSummaryContent
type RunPermissionSummaryContent struct {
	SkillVersionID uuid.UUID `json:"skill_version_id"`
	// The exact package bytes this run would execute. In the hash because "which code runs" is a
	// permission fact.
	SkillContentHash string    `json:"skill_content_hash"`
	TestCaseID       uuid.UUID `json:"test_case_id"`
	// Every file the run will be able to read, oldest upload first.
	Datasets          []RunPermissionSummaryContentDatasetsItem `json:"datasets"`
	DatasetTotalBytes int64                                     `json:"dataset_total_bytes"`
	// Whether the package carries runnable code, answered by re-scanning the stored package rather than by
	// reading a projected flag - the scan covers the exact bytes that would be executed. Nothing is
	// executed to produce it (iron rule 1).
	Scripts RunPermissionSummaryContentScripts `json:"scripts"`
	// The agent's own tools, inside the sandbox and nowhere else. There is no per-tool grant to disclose
	// because there is none to make: the isolation boundary is the container, not a tool list.
	Tools []string `json:"tools"`
	// Always empty in the MVP, and shown as empty rather than omitted. A missing row reads as a question
	// nobody asked; an empty one states that the answer is none (remote MCP is out of first release).
	McpServers []string                           `json:"mcp_servers"`
	Network    RunPermissionSummaryContentNetwork `json:"network"`
	// Names only, never values (iron rule 11, NFR-002). The values are per-run short-lived credentials
	// minted at dispatch, and they appear in no screen, log or trace.
	InjectedSecrets []string `json:"injected_secrets"`
	// Who would run the workload and how strongly it is isolated. Best effort: an empty or unreachable
	// fleet reports `unassigned` rather than failing the summary - refusing incompatible work is POST
	// /skills/{id}/runs' job, not this one's.
	Provider       RunPermissionSummaryContentProvider `json:"provider"`
	ResourceLimits RunResourceLimits                   `json:"resource_limits"`
}

